import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.*;
import java.util.stream.Stream;

class DiscountCalculatorTest {

    // @ValueSource: single primitive or String values
    @ParameterizedTest
    @ValueSource(ints = {10, 50, 100})
    void validDiscountPercentages(int percent) {
        var discount = new DiscountCalculator();
        assertDoesNotThrow(() -> discount.setPercent(percent));
    }

    // @CsvSource: multiple parameters per test execution
    @ParameterizedTest
    @CsvSource({"100, 10, 90", "200, 25, 150", "50, 50, 25"})
    void discountCalculation(double price, int percent, double expected) {
        var calculator = new DiscountCalculator();
        assertEquals(expected, calculator.apply(price, percent));
    }

    // @MethodSource: complex objects via Stream
    @ParameterizedTest
    @MethodSource("orderScenarios")
    void orderDiscountRules(Order order, double expected) {
        assertEquals(expected, calculator.calculateDiscount(order));
    }

    static Stream<Arguments> orderScenarios() {
        return Stream.of(
            Arguments.of(new Order(100.0, "PREMIUM"), 20.0),
            Arguments.of(new Order(100.0, "STANDARD"), 10.0)
        );
    }

    // @NullAndEmptySource: tests null and empty string
    @ParameterizedTest
    @NullAndEmptySource
    void rejectsInvalidCodes(String promoCode) {
        assertThrows(IllegalArgumentException.class,
            () -> calculator.applyPromo(promoCode));
    }
}

import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvSource;
import static org.junit.jupiter.api.Assertions.*;

class AgeValidatorTest {

    private final AgeValidator validator = new AgeValidator();

    @ParameterizedTest
    @CsvSource({
        "0, false",      // below minimum
        "1, true",       // lower boundary
        "18, true",      // typical valid value
        "120, true",     // upper boundary
        "121, false",    // above maximum
        "-5, false"      // negative edge case
    })
    void ageValidationBoundaries(int age, boolean expectedValid) {
        assertEquals(expectedValid, validator.isValid(age));
    }

    @ParameterizedTest
    @CsvSource({
        "1000, 10, 900.0",     // standard discount
        "0, 10, 0.0",          // zero price
        "100, 0, 100.0",       // zero discount
        "50, 100, 0.0",        // full discount
        "1000, 15, 850.0"      // mid-range case
    })
    void priceDiscountCalculation(double price, int discountPercent, double expected) {
        var calculator = new PriceCalculator();
        var result = calculator.applyDiscount(price, discountPercent);
        assertEquals(expected, result, 0.01);  // delta for double comparison
    }
}

import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.MethodSource;
import org.junit.jupiter.params.provider.Arguments;
import java.util.stream.Stream;
import static org.junit.jupiter.api.Assertions.*;

class OrderProcessorTest {

    private final OrderProcessor processor = new OrderProcessor();

    @ParameterizedTest
    @MethodSource("orderScenarios")  // points to static method below
    void processOrderWithDifferentStates(Order order, boolean shouldSucceed, String expectedMessage) {
        var result = processor.process(order);
        assertEquals(shouldSucceed, result.isSuccess());
        assertTrue(result.getMessage().contains(expectedMessage));
    }

    static Stream<Arguments> orderScenarios() {
        return Stream.of(
            Arguments.of(
                new Order(1L, "PENDING", List.of(new LineItem("ITEM-1", 2))),
                true,
                "processed successfully"
            ),
            Arguments.of(
                new Order(2L, "CANCELLED", List.of()),
                false,
                "cannot process cancelled order"
            ),
            Arguments.of(
                new Order(3L, "PENDING", List.of()),  // no items
                false,
                "order has no items"
            )
        );
    }

    // Convention: method name matches test name when @MethodSource has no value
    @ParameterizedTest
    @MethodSource  // looks for static method 'userValidationCases'
    void userValidationCases(User user, boolean expectedValid) {
        assertEquals(expectedValid, new UserValidator().isValid(user));
    }

    static Stream<Arguments> userValidationCases() {
        return Stream.of(
            Arguments.of(new User("john@example.com", 25), true),
            Arguments.of(new User("invalid-email", 25), false),
            Arguments.of(new User("jane@example.com", 15), false)  // underage
        );
    }
}

import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvSource;
import static org.junit.jupiter.api.Assertions.*;

class BoundaryTestExamples {

    @ParameterizedTest(name = "Age {0} should be {1}")
    @CsvSource({
        "0, false",      // just below minimum (min-1)
        "1, true",       // lower boundary (min)
        "60, true",      // representative valid middle
        "120, true",     // upper boundary (max)
        "121, false",    // just above maximum (max+1)
        "-10, false"     // far below (edge case)
    })
    void ageValidationBoundaries(int age, boolean expectedValid) {
        var validator = new AgeValidator(1, 120);
        assertEquals(expectedValid, validator.isValid(age),
            () -> "Age " + age + " validation failed");
    }

    @ParameterizedTest(name = "String length {0} should be {1}")
    @CsvSource({
        "'', false",           // empty string (special boundary)
        "a, false",            // length 1 (below minimum)
        "ab, false",           // length 2 (below minimum)
        "abc, true",           // length 3 (minimum)
        "abcdefgh, true",      // middle valid
        "abcdefghij, true",    // length 10 (maximum)
        "abcdefghijk, false"   // length 11 (above maximum)
    })
    void usernameLengthValidation(String username, boolean expectedValid) {
        var validator = new UsernameValidator(3, 10);
        assertEquals(expectedValid, validator.isValid(username));
    }

    @ParameterizedTest
    @CsvSource({
        "0.0, true",       // zero boundary
        "0.01, true",      // smallest positive
        "999.99, true",    // just below 1000
        "1000.0, true",    // exact boundary
        "1000.01, false",  // just above
        "-0.01, false"     // negative
    })
    void paymentAmountBoundaries(double amount, boolean expectedValid) {
        var validator = new PaymentValidator(0.0, 1000.0);
        assertTrue(expectedValid == validator.isValidAmount(amount));
    }
}
